// Validate response
const r = $input.first().json;
if (!r.access_token) {
  throw new Error('TikTok refresh failed: ' + JSON.stringify(r));
}

const newToken = r.access_token;
const expiresIn = r.expires_in || 86400;
const newRefreshToken = r.refresh_token;

// Prepare payload de update N8N credential
// Credential 'Header Auth' co structure: { name, type, data: { name: 'Authorization', value: 'Bearer XXX' } }
return {
  json: {
    new_access_token:  newToken,
    new_refresh_token: newRefreshToken,
    expires_in:        expiresIn,
    expires_at:        new Date(Date.now() + (expiresIn * 1000)).toISOString(),
    bearer_header:     'Bearer ' + newToken,
    refreshed_at:      new Date().toISOString()
  }
};

